script:
//
/* Smart Choice loader: يجلب أحدث smart-choice.js من GitHub (كاش 5 دقائق) بدل الاعتماد على كاش CDN الطويل. */
(function () {
  var raw = "https://raw.githubusercontent.com/tahattaha41/Smart-Choice/main/assets/js/smart-choice.js";
  var cdn = "https://cdn.jsdelivr.net/gh/tahattaha41/Smart-Choice@main/assets/js/smart-choice.js";
  function viaCdn() { var s = document.createElement("script"); s.src = cdn + "?v=" + Math.floor(Date.now() / 600000); document.head.appendChild(s); }
  try {
    fetch(raw + "?t=" + Math.floor(Date.now() / 300000), { credentials: "omit" })
      .then(function (r) { if (!r.ok) { throw new Error(r.status); } return r.text(); })
      .then(function (code) { var s = document.createElement("script"); s.textContent = code; document.head.appendChild(s); })
      .catch(viaCdn);
  } catch (e) { viaCdn(); }
})();
//

window.dataLayer = window.dataLayer || [];
function gtag(){dataLayer.push(arguments);}
gtag('js', new Date());
gtag('config', 'G-BRZP957SQ4');

// /*SC-AD-GATE*/
  (function(){
    var CLIENT='ca-pub-1235197294708204',MIN=350,tries=0,done=false;
    function words(el){return (el.innerText||'').split(/\s+/).filter(function(w){return w.length>1;}).length;}
    function eligible(){
      var m=document.querySelector('meta[name="sc-pagetype"]'),pt=m?m.getAttribute('content'):'';
      var path=location.pathname;
      if(pt!=='item'&&pt!=='static_page')return false;
      if(path==='/'||/^\/search/.test(path)||/\/404/.test(path))return false;
      var main=document.querySelector('#main-content');if(!main)return false;
      if(main.querySelector('.sc-tabs,#sc-admin,.sc-admin,#sc-rates-board,.hero,.hcalc'))return false;
      if(pt==='static_page'&&!main.querySelector('.sc-tool,.sc-guide,.sc-prose'))return false;
      var c=main.cloneNode(true);c.querySelectorAll('nav,.sc-share-bar,.sc-related,form,button,script,style').forEach(function(n){n.remove();});
      return (c.textContent||'').split(/\s+/).filter(function(w){return w.length>1;}).length>=MIN;
    }
    function load(){if(done)return;done=true;var s=document.createElement('script');s.async=true;s.crossOrigin='anonymous';s.src='https://pagead2.googlesyndication.com/pagead/js/adsbygoogle.js?client='+CLIENT;document.head.appendChild(s);}
    function check(){if(done)return;tries++;try{if(eligible()){load();return;}}catch(e){}if(tries<8)setTimeout(check,900);}
    if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',function(){setTimeout(check,600);});else setTimeout(check,600);
  })();
  //
